draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Bird flying
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 50*Math.sin(t), H/2, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50*Math.sin(t), H/2);
  ctx.lineTo(W/2 + 50*Math.sin(t) + 30*Math.cos(t), H/2 + 30*Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50*Math.sin(t), H/2);
  ctx.lineTo(W/2 + 50*Math.sin(t) - 30*Math.cos(t), H/2 - 30*Math.sin(t));
  ctx.stroke();

  // Fish swimming
  ctx.beginPath();
  ctx.arc(W/2 - 100 + 20*Math.sin(2*t), H/2 + 50, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + 20*Math.sin(2*t), H/2 + 50);
  ctx.lineTo(W/2 - 100 + 20*Math.sin(2*t) + 10*Math.cos(2*t), H/2 + 50 + 10*Math.sin(2*t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + 20*Math.sin(2*t), H/2 + 50);
  ctx.lineTo(W/2 - 100 + 20*Math.sin(2*t) - 10*Math.cos(2*t), H/2 + 50 - 10*Math.sin(2*t));
  ctx.stroke();

  ctx.restore();
}
